INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'HONGKONG','HARBOUR','尖沙咀海滨散步','Tsim Sha Tsui Waterfront','尖沙咀钟楼 → 尖沙咀海滨花园 → 星光大道 → 香港艺术馆。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','半天','ALL','/images/explore/hd/1280/hong-kong-06-clock-tower.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='尖沙咀钟楼' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='尖沙咀海滨花园' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='星光大道' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='香港艺术馆' ORDER BY id LIMIT 1)),1,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='HONGKONG' AND code='HARBOUR');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'HONGKONG','CENTRAL','中环旧建筑与坡道','Central Heritage Walk','中环街市 → 中环至半山自动扶梯 → 大馆 → PMQ (元创方) → 文武庙。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','半天','ALL','/images/explore/hd/1280/hong-kong-13-central-market.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='中环街市' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='中环至半山自动扶梯' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='大馆' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='PMQ (元创方)' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='文武庙' ORDER BY id LIMIT 1)),2,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='HONGKONG' AND code='CENTRAL');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'HONGKONG','PEAK','由中环前往山顶','Central to the Peak','香港公园 → 中银大厦 → 山顶缆车 → 太平山顶。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','半天，含缆车交通','ALL','/images/explore/hd/1280/hong-kong-19-hong-kong-park.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='香港公园' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='中银大厦' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='山顶缆车' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='太平山顶' ORDER BY id LIMIT 1)),3,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='HONGKONG' AND code='PEAK');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'HONGKONG','WEST-KOWLOON','西九文化与海滨','West Kowloon Culture','香港故宫文化博物馆 → 西九文化区 → M+博物馆。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','一天，展览可择一','ALL','/images/explore/hd/1280/hong-kong-11-palace-museum.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='香港故宫文化博物馆' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='西九文化区' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='M+博物馆' ORDER BY id LIMIT 1)),4,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='HONGKONG' AND code='WEST-KOWLOON');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'HONGKONG','KOWLOON','九龙园林与街市','Kowloon Gardens and Markets','志莲净苑 → 南莲园池 → 黄大仙祠 → 女人街 → 庙街。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','一天，需搭乘港铁','ALL','/images/explore/hd/1280/hong-kong-23-chi-lin.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='志莲净苑' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='南莲园池' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='黄大仙祠' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='女人街' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='庙街' ORDER BY id LIMIT 1)),5,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='HONGKONG' AND code='KOWLOON');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'HONGKONG','LANTAU','昂坪与大澳山海线','Lantau Island Day','天坛大佛 → 宝莲禅寺 → 大澳。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','一天，需换乘公共交通','ALL','/images/explore/hd/1280/hong-kong-28-tian-tan-buddha.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='天坛大佛' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='宝莲禅寺' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='香港' AND name='大澳' ORDER BY id LIMIT 1)),6,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='HONGKONG' AND code='LANTAU');
INSERT INTO official_cities(code,name,country_code,description,cover_image,status,theme,created_at) SELECT 'TAIPEI','台北','TW','从庙口与老街走到城市天际线，在市场、公园和温泉街区之间认识台北。','/images/explore/hd/1280/taipei-01-taipei-101.webp','ACTIVE','街巷、夜市与山城生活',UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_cities WHERE code='TAIPEI');
