INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'TAIPEI','OLD-TAIPEI','艋舺与西门街巷','Old Taipei Walk','艋舺龙山寺 → 剥皮寮历史街区 → 西门红楼 → 西门町。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','半天','ALL','/images/explore/hd/1280/taipei-06-longshan.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='艋舺龙山寺' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='剥皮寮历史街区' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='西门红楼' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='西门町' ORDER BY id LIMIT 1)),1,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='TAIPEI' AND code='OLD-TAIPEI');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'TAIPEI','DADAOCHENG','大稻埕老街到河岸','Dadaocheng Riverside','迪化街 → 大稻埕码头 → 宁夏夜市。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','半天','ALL','/images/explore/hd/1280/taipei-10-dihua-street.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='迪化街' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='大稻埕码头' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='宁夏夜市' ORDER BY id LIMIT 1)),2,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='TAIPEI' AND code='DADAOCHENG');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'TAIPEI','CITY-SKYLINE','信义建筑与象山视角','Taipei Skyline','松山文创园区 → 台北101 → 象山。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','半天，含登山步道','ALL','/images/explore/hd/1280/taipei-14-songshan-creative.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='松山文创园区' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='台北101' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='象山' ORDER BY id LIMIT 1)),3,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='TAIPEI' AND code='CITY-SKYLINE');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'TAIPEI','CITY-CULTURE','广场、文创与公园','Cultural Taipei','台北植物园 → 中正纪念堂 → 自由广场 → 两厅院 → 华山1914文化创意产业园区。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','一天，需搭乘捷运','ALL','/images/explore/hd/1280/taipei-24-botanical-garden.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='台北植物园' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='中正纪念堂' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='自由广场' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='两厅院' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='华山1914文化创意产业园区' ORDER BY id LIMIT 1)),4,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='TAIPEI' AND code='CITY-CULTURE');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'TAIPEI','BEITOU','北投温泉文化散步','Beitou Hot Spring Walk','台北市立图书馆北投分馆 → 北投温泉博物馆 → 北投地热谷。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','半天','ALL','/images/explore/hd/1280/taipei-26-beitou-library.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='台北市立图书馆北投分馆' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='北投温泉博物馆' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='北投地热谷' ORDER BY id LIMIT 1)),5,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='TAIPEI' AND code='BEITOU');
INSERT INTO official_routes(city_code,code,title,english_title,description,duration_hint,season,cover_image,place_ids,sort_order,created_at) SELECT 'TAIPEI','MUSEUM-AND-MARKET','士林文化与夜市','Shilin Culture and Food','台北故宫博物院 → 士林官邸 → 士林夜市。可按体力、开放安排与天气调整；预计时长为游览建议，不含固定班次。','一天，需搭乘公共交通','ALL','/images/explore/hd/1280/taipei-17-palace-museum.webp',CONCAT_WS(',',(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='台北故宫博物院' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='士林官邸' ORDER BY id LIMIT 1),(SELECT id FROM places WHERE source_type='OFFICIAL' AND city='台北' AND name='士林夜市' ORDER BY id LIMIT 1)),6,UTC_TIMESTAMP() WHERE NOT EXISTS (SELECT 1 FROM official_routes WHERE city_code='TAIPEI' AND code='MUSEUM-AND-MARKET');
